            "options": [],
            "correctKey": null,
            "answerRaw": "✔ Cevap: EMR (elektronik tıbbi kayıt), tek bir sağlayıcının (ör. bir\n   doktor muayenehanesi) ofisinde toplanan standart klinik verileri içerir:\n   tanılar, ilaçlar, aşı kayıtları gibi. Bilgiler genellikle o kuruluşun\n   dışında kolayca paylaşılmaz. EHR (elektronik sağlık kaydı) ise hastanın\n   toplam sağlığına dair verileri içerir ve hastanın tüm tıbbi geçmişinin\n   kapsamlı görünümünü sunar. EHR, birden fazla kuruluştaki yetkili\n   sağlayıcılar ve personelle paylaşılmak üzere tasarlanmıştır.",
